ALTER TABLE public.consents ADD COLUMN image_generation boolean NOT NULL DEFAULT false;
CREATE TABLE public.beard_profiles (user_id uuid PRIMARY KEY, data jsonb NOT NULL DEFAULT '{}', updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.beard_profiles TO authenticated;
GRANT ALL ON public.beard_profiles TO service_role;
ALTER TABLE public.beard_profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY beard_owner ON public.beard_profiles FOR ALL TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid());
CREATE TABLE public.generated_references (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL, package_id uuid REFERENCES public.packages(id) ON DELETE CASCADE, slot text NOT NULL, prompt text NOT NULL, status text NOT NULL DEFAULT 'ready', path text, error text, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT, INSERT, UPDATE, DELETE ON public.generated_references TO authenticated;
GRANT ALL ON public.generated_references TO service_role;
ALTER TABLE public.generated_references ENABLE ROW LEVEL SECURITY;
CREATE POLICY references_owner_read ON public.generated_references FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE POLICY references_owner_write ON public.generated_references FOR ALL TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid() AND (package_id IS NULL OR EXISTS (SELECT 1 FROM public.packages p WHERE p.id=package_id AND p.user_id=auth.uid())));
CREATE UNIQUE INDEX references_one_active ON public.generated_references(user_id, COALESCE(package_id::text,'avatar'),slot) WHERE status IN ('ready','generating');
CREATE INDEX references_lookup ON public.generated_references(user_id,package_id,slot,created_at DESC);
CREATE TABLE public.image_access_state (user_id uuid PRIMARY KEY, denied boolean NOT NULL DEFAULT false, message text, updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.image_access_state TO authenticated;
GRANT ALL ON public.image_access_state TO service_role;
ALTER TABLE public.image_access_state ENABLE ROW LEVEL SECURITY;
CREATE POLICY image_access_owner_read ON public.image_access_state FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE POLICY references_storage_consent ON storage.objects AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK (bucket_id <> 'user-photos' OR name NOT LIKE '%/reference-%' OR EXISTS (SELECT 1 FROM public.consents c WHERE c.user_id=auth.uid() AND c.image_generation AND c.photo_processing));